SELECT id, product_id, quantity, last_restock, SUM(quantity) OVER w_ordered AS running_sum_quantity, AVG(quantity) OVER w_ordered AS running_avg_quantity, COUNT(quantity) OVER w_ordered AS running_count_quantity, FIRST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_quantity FROM inventory WINDOW w_ordered AS (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
